{"decisions": [{"case_id": "bbe14e22bc3b75825b3dfdb75d3f670f03e13b2860499270adc8c294ef051e98", "consensus": false, "vulnerability_class": "deflationary token supply manipulation in reward distribution formula causing imbalanced LP value extraction", "reentrancy_label": null, "reasoning": "CertiK attributes the exploit to 'a vulnerability in the way SEAMAN handles GVC distribution on LP deposits' causing 'a spike in GVC', but provides no mechanistic detail about fee-on-transfer arithmetic or reward recalculation. PeckShield reports only price impact ($GVC -81%, ~$7.7k loss) with no technical root cause. The two analyses disagree: CertiK frames the cause as a GVC distribution logic flaw while PeckShield offers no mechanism at all. Without shared technical granularity, consensus cannot be established.", "independence_basis": "Both are independent security firms (CertiK and PeckShield) with distinct Twitter accounts and separate artifact hashes.", "attack_transaction_hashes": ["0x6f1af27d08b10caa7e96ec3d580bf39e29fd5ece00abda7d8955715403bf34a8"], "observations": [{"publisher": "CertiK", "url": "https://twitter.com/CertiKAlert/status/1597513374841044993", "quote": "exploited a vulnerability in the way SEAMAN handles GVC distribution on LP deposits"}, {"publisher": "PeckShield", "url": "https://twitter.com/peckshield/status/1597493955939405825", "quote": "SEAMAN is exploited (w/ ~$7.7k) $GVC has dropped -81%"}]}, {"case_id": "c9f6965255c635278ee421100ff72921e13b87f6b303366602b7ea00ce6444dd", "consensus": true, "vulnerability_class": "deflationary token fee-on-transfer exploitation via targeted address triggering undisclosed fee-claim mechanic to manipulate LP pool price", "reentrancy_label": false, "reasoning": "BlockSec identifies the root cause as a deflationary token where transfers to a specific address (0x40ed17221b...07e3) trigger fee claims, and the attacker abused this to manipulate the BNB-AES pool price. PeckShield independently corroborates the price manipulation mechanism with the same outcome (~$61.6k loss, AES -89%). Both describe the same mechanistic root cause: the token's transfer-to-specific-address fee-claim behavior enabling LP price manipulation. The PoC confirms this by targeting address 0x40eD17221b3B2D8455F4F1a05CAc6b77c5f707e3 repeatedly via skim and transferring 50% of balance to it before calling distributeFee().", "independence_basis": "BlockSec and PeckShield are independent security firms with distinct social accounts, separate artifact hashes, and no overlapping authorship.", "attack_transaction_hashes": ["0xca4d0d24aa448329b7d4eb81be653224a59e7b081fc7a1c9aad59c5a38d0ae19"], "observations": [{"publisher": "BlockSec", "url": "https://twitter.com/BlockSecTeam/status/1600442137811689473", "quote": "attacker abused this feature to manipulate the price of the BNB-AES pool"}, {"publisher": "PeckShield", "url": "https://twitter.com/peckshield/status/1600418002163625984", "quote": "AES is exploited (w/ ~61.6k) $AES has dropped -89%"}]}, {"case_id": "965c5b56cadde0ec6d74e0984aade9bab054f7d69495e25775003390b71875e3", "consensus": true, "vulnerability_class": "admin misconfiguration allowing unauthorized router address leading to arbitrary transferFrom execution on approved user balances", "reentrancy_label": false, "reasoning": "BlockSec identifies the root cause as 'USDC had been added as a router (by the admin), leading to an arbitrary function call with USDC contract' enabling the attacker to invoke transferFrom on victim allowances. PeckShield independently corroborates: 'The hack is made possible due to mistakenly adding USDC into supported routers. Also with a lack of validation in routerCallNative, the hacker can drain all funds from users who have approvals to the RubicProxy.' Both describe the identical mechanistic root cause: admin-added USDC as a router address without validation, permitting arbitrary function calls that execute transferFrom against user-approved USDC balances.", "independence_basis": "BlockSec and PeckShield are independent security firms with distinct Twitter accounts, separate artifact hashes, and no shared authorship.", "attack_transaction_hashes": ["0x9a97d85642f956ad7a6b852cf7bed6f9669e2c2815f3279855acf7f1328e7d46"], "observations": [{"publisher": "BlockSec", "url": "https://twitter.com/BlockSecTeam/status/1606993118901198849", "quote": "attacker abused that USDC had been added as a router leading to an arbitrary function call with USDC contract"}, {"publisher": "PeckShield", "url": "https://twitter.com/peckshield/status/1606937055761952770", "quote": "mistakenly adding USDC into supported routers lack of validation in routerCallNative the hacker can drain all funds"}]}]}
